window.kbPageData["views/entry/k-8026f07aab3cc5a0"] = {"key":"entry/k-8026f07aab3cc5a0","state":{"route":"entry/k-8026f07aab3cc5a0"},"node":{"id":"k-8026f07aab3cc5a0","mode":"k","title":"建设高素质干部队伍","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"3.建设高素质干部队伍\n《决定》从 6 个方面作出部署：一是坚持正确用人导向。强调坚持党管干部原则，落\n实新时代好干部标准，大力选拔任用对党忠诚、表里如一、担当尽责、实绩突出、清正廉\n洁的干部，坚决不用那些畏难避事、庸懒无为、作风漂浮的人，坚决清除那些对党不忠、\n阳奉阴违、以权谋私的人。二是精准科学…","sources":[{"id":"83048902814807e7","label":"建设高素质干部队伍","topic":"党政制度与理论","category":"非时政","text":"3.建设高素质干部队伍\n《决定》从 6 个方面作出部署：一是坚持正确用人导向。强调坚持党管干部原则，落\n实新时代好干部标准，大力选拔任用对党忠诚、表里如一、担当尽责、实绩突出、清正廉\n洁的干部，坚决不用那些畏难避事、庸懒无为、作风漂浮的人，坚决清除那些对党不忠、\n阳奉阴违、以权谋私的人。二是精准科学选人用人。坚持组织选人、公正用人、以事择人，\n严格执行干部选拔任用原则和程序，坚决整治用人上的不正之风。三是推动干部树立和践\n行正确政绩观。深化政绩观教育，改进推动高质量发展政绩考核，健全有效防范和纠治政\n绩观偏差工作机制，引导干部为人民出政绩、以实干出政绩。四是增强干部干事创业本\n领。加强干部思想淬炼、政治历练、实践锻炼、专业训练，增强推动高质量发展本领、服\n务群众本领、防范化解风险本领、运用法治思维和法治方式开展工作本领。五是提高培养\n选拔优秀年轻干部质量。坚持培养和管理并重，引导年轻干部走健康成长之路。六是加强\n干部管理监督。从高级干部抓起，加强干部全方位管理和经常性监督。","source":{"doc":"41195a191a57c1c36332","first":16,"last":16,"page":16,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-8026f07aab3cc5a0":[]}};
